import './building-entities.js?v=103';
const Buildings=globalThis.BoroughBuildings;
// Saved household members and daily routines, connected to the live road agents.
export class Residents {
 constructor(world,traffic,transit=null){this.transit=transit;this.walking=transit?.walking;this.world=world;this.traffic=traffic;world.citizens ||= {version:1,time:0,nextId:1,residents:[]};this.state=world.citizens;this.agents=new Map();this.reconcile();this.restore();}
 reconcile(){const s=this.state,w=this.world,byHome=new Map();for(const r of s.residents){if(!byHome.has(r.home))byHome.set(r.home,[]);byHome.get(r.home).push(r);}const kept=[];for(const [home,t]of Buildings.entries(w)){if(t.type!=='residential'||!t.level)continue;const count=Math.floor(t.people||0),existing=byHome.get(home)||[];for(let i=0;i<count;i++){const id=s.nextId,r=existing[i]||{id:s.nextId++,home,household:home+':'+Math.floor(i/3),work:null,location:home,activity:'Home',nextAt:s.time+2+id%18,workdays:0,shopping:0};kept.push(r);}}const ids=new Set(kept.map(r=>r.id));for(const [id,a]of this.agents)if(!ids.has(id)){a.active=false;this.agents.delete(id);}s.residents=kept;this.byId=new Map(kept.map(r=>[r.id,r]));this.jobs=new Map();this.shops=[];for(const [i,t]of Buildings.entries(w)){if(t.level>0&&!t.construction){const capacity=this.traffic.engine.jobCapacity(t);if(capacity)this.jobs.set(i,{capacity,filled:0});if(this.traffic.engine.hasShops(t))this.shops.push(i);}}for(const r of kept){const job=this.jobs.get(r.work);if(!job||job.filled>=job.capacity)r.work=null;else job.filled++;}this.cursor=(this.cursor||0)%Math.max(1,kept.length);for(const r of kept)if(r.trip&&!Buildings.get(w,r.trip.to)?.level){const a=this.agents.get(r.id);if(a)a.active=false;this.agents.delete(r.id);delete r.trip;r.activity='Trip cancelled · destination removed';r.nextAt=s.time+5;}}
 restore(){for(const r of this.state.residents)if(r.trip)this.depart(r,r.trip.to,r.trip.purpose,true);}
 depart(r,to,purpose,restore=false){if(!restore&&r.location===to){this.arrive(r,to,purpose);return true;}if(!restore&&r.id%3===0&&this.walking?.request(r,to,purpose,36))return true;if(!restore&&this.transit?.request(r,to,purpose))return true;const from=restore?r.trip.from:r.location,route=this.traffic.between(from,to);if(!route){if(!restore&&this.walking?.request(r,to,purpose))return true;r.activity='Waiting for road access';r.nextAt=this.state.time+10;return false;}const a=this.traffic.agents.find(a=>!a.active&&a.kind!=='bus');if(!a)return false;if(!restore&&this.traffic.agents.some(b=>b.active&&Math.hypot(b.x-route.points[0].x,b.z-route.points[0].z)<1.7))return false;const old=restore?r.trip:null;let progress=old?Math.min(old.segment,Math.max(0,route.points.length-2)):0,restoredDistance=old?.distance||0;
// Older saves may refer to the pre-rounded route. Project only mismatched positions.
if(old){const p=route.points[progress],q=route.points[progress+1],length=Math.hypot(q.x-p.x,q.z-p.z)||1,f=Math.min(1,restoredDistance/length);if(Math.hypot(p.x+(q.x-p.x)*f-old.x,p.z+(q.z-p.z)*f-old.z)>.1){let best=Infinity;for(let k=0;k<route.points.length-1;k++){const a=route.points[k],b=route.points[k+1],dx=b.x-a.x,dz=b.z-a.z,l=dx*dx+dz*dz;if(!l)continue;const f=Math.max(0,Math.min(1,((old.x-a.x)*dx+(old.z-a.z)*dz)/l)),d=(a.x+dx*f-old.x)**2+(a.z+dz*f-old.z)**2;if(d<best){best=d;progress=k;restoredDistance=f*Math.sqrt(l);}}}}
Object.assign(a,{previousX:undefined,previousZ:undefined,speed:0,stopTime:0,stopJunction:null,active:true,arrived:false,residentId:r.id,trip:{destination:to,cells:[route.cells],roads:new Set(route.cells)},phase:'resident',points:route.points,segment:progress,distance:Math.min(restoredDistance,Math.hypot(route.points[progress+1].x-route.points[progress].x,route.points[progress+1].z-route.points[progress].z)),dwell:0,x:old?.x??route.points[0].x,z:old?.z??route.points[0].z,heading:old?.heading||0});r.trip={from,to,purpose,segment:a.segment,distance:a.distance,x:a.x,z:a.z,heading:a.heading};r.activity=purpose==='work'?'Commuting to work':purpose==='shop'?'Going shopping':'Returning home';this.agents.set(r.id,a);return true;}
 accessible(from,to){return from===to||!!this.traffic.between(from,to)||!!this.walking?.canReach(from,to);}
 arrive(r,to,purpose){r.location=to;delete r.trip;r.activity=purpose==='work'?'Working':purpose==='shop'?'Shopping':'Home';if(purpose==='work')r.workdays++;if(purpose==='shop')r.shopping++;r.nextAt=this.state.time+(purpose==='work'?24:purpose==='shop'?8:20)+r.id%7;}
 destination(r){
  if(r.activity==='Working'){for(const shop of this.shops)if(shop!==r.location&&this.accessible(r.location,shop)&&this.accessible(shop,r.home))return[shop,'shop'];if(this.shops.includes(r.location))return[r.location,'shop'];return[r.home,'home'];}
  if(r.activity==='Shopping')return[r.home,'home'];
  if(r.location===r.home){if(r.work!==null)return[r.work,'work'];if(r.id%3!==0){for(const [i,job]of this.jobs){if(job.filled<job.capacity&&this.accessible(r.home,i)&&this.accessible(i,r.home)){job.filled++;r.work=i;return[i,'work'];}}}for(const shop of this.shops)if(this.accessible(r.location,shop)&&this.accessible(shop,r.home))return[shop,'shop'];return null;}
  return[r.home,'home'];
 }

 update(dt){if(dt<=0)return;this.state.time+=dt;for(const [id,a]of this.agents){const r=this.byId.get(id);if(!r)continue;if(a.active){Object.assign(r.trip,{segment:a.segment,distance:a.distance,x:a.x,z:a.z,heading:a.heading});continue;}this.agents.delete(id);if(!a.arrived){r.activity='Waiting for road access';r.nextAt=this.state.time+10;continue;}a.arrived=false;const to=r.trip.to,purpose=r.trip.purpose;this.arrive(r,to,purpose);}
 this.clock=(this.clock||0)+dt;if(this.clock<.5)return;this.clock=0;const people=this.state.residents;if(!people.length)return;for(let n=0;n<Math.min(Math.max(12,Math.ceil(people.length/20)),people.length);n++){const r=people[this.cursor++%people.length];if(r.walk||r.transit||this.agents.has(r.id)||r.nextAt>this.state.time)continue;if(r.trip){this.depart(r,r.trip.to,r.trip.purpose,true);continue;}const destination=this.destination(r);if(destination)this.depart(r,...destination);else{r.activity='Home · no reachable jobs or shops';r.nextAt=this.state.time+10;}}}
 name(r){return ['Avery','Jordan','Sam','Taylor','Riley','Alex','Morgan','Casey'][r.id%8]+' '+['Chen','Patel','Wilson','Garcia','Kim','Brown','Singh','Martin'][Math.floor(r.id/8)%8]+' #'+r.id;}
 get summary(){const residents=this.state.residents;return{population:residents.length,households:new Set(residents.map(r=>r.household)).size,employed:residents.filter(r=>r.work!==null).length,travelling:this.agents.size+residents.filter(r=>r.transit||r.walk).length,working:residents.filter(r=>r.activity==='Working').length,shopping:residents.filter(r=>r.activity==='Shopping').length};}
}
